//! 생성 파일 판정 — Linguist `lib/linguist/generated.rb`(v9.7.0)에서 **경로 규칙과 앞 줄만 보는 규칙**을 손으로 옮긴 것
//! (결정 M1-D20, `docs/design/12-m1-plan.md` §4). Linguist 의 generated 판정은 YAML 이 아니라 Ruby 코드라 표 변환에 들지 않는다.
//!
//! 옮긴 규칙은 [`PATH_RULES`] · [`CONTENT_RULES`] 의 이름(generated.rb 의 메서드 이름)이 목록이다. 앞부분만 받으므로 내용 규칙의
//! 「줄」은 받은 앞부분의 줄이다(`minified_files?` 의 평균 줄 길이도 앞부분으로 잰다).
//!
//! 옮기지 않은 규칙과 이유 — 파일 끝이나 전체를 봐야 한다:
//! - `has_source_map?`(끝 2줄의 `sourceMappingURL`), `generated_net_docfile?`(끝에서 둘째 줄), `vcr_cassette?`(끝에서 둘째 줄),
//!   `compiled_coffeescript?` 의 모듈 감싸기 판정(끝 두 줄과 전체 점수 — 첫 줄 `// Generated by` 규칙은 옮겼다),
//!   `generated_postscript?`(내용 전체 검색).
//! - `generated_html?` 의 `<meta name="generator">` 판정(속성 파서가 필요하다 — pkgdown · Doxygen · 자동 생성 머리 줄은 옮겼다).
//!
//! Linguist 에 없는 규칙(예: `target/`, `dist/`)은 더하지 않는다 — GitHub 와 같은 결과를 내는 것이 목적이다.

use std::sync::LazyLock;

use regex::{Regex, RegexSet};

/// 경로(저장소 기준, `/` 구분)만 보는 규칙. 이름은 generated.rb 의 메서드 이름이다.
pub const PATH_RULES: &[(&str, &str)] = &[
    ("intellij_file?", r"(?:^|/)\.idea/"),
    ("cocoapods?", r"(?:^Pods|/Pods)/"),
    ("carthage_build?", r"(?:^|/)Carthage/Build/"),
    ("generated_graphql_relay?", r"__generated__/"),
    (
        "generated_net_designer_file?",
        r"(?i)\.designer\.(?:cs|vb)$",
    ),
    (
        "generated_net_specflow_feature_file?",
        r"(?i)\.feature\.cs$",
    ),
    ("composer_lock?", r"composer\.lock"),
    ("cargo_lock?", r"Cargo\.lock"),
    ("cargo_orig?", r"Cargo\.toml\.orig"),
    ("deno_lock?", r"deno\.lock"),
    ("flake_lock?", r"(?:^|/)flake\.lock$"),
    ("bazel_lock?", r"(?:^|/)MODULE\.bazel\.lock$"),
    ("node_modules?", r"node_modules/"),
    // 원본은 앞뒤 보기로 「`-` 로 시작하거나 끝나지 않는 이름표」를 쓴다. 같은 뜻을 앞뒤 보기 없이 적었다.
    (
        "go_vendor?",
        r"vendor/(?:[0-9A-Za-z](?:[-0-9A-Za-z]*[0-9A-Za-z])?\.)+(?:com|edu|gov|in|me|net|org|fm|io)",
    ),
    ("go_lock?", r"(?:Gopkg|glide)\.lock"),
    ("package_resolved?", r"Package\.resolved"),
    ("poetry_lock?", r"poetry\.lock"),
    ("pdm_lock?", r"pdm\.lock"),
    ("uv_lock?", r"uv\.lock"),
    ("pixi_lock?", r"pixi\.lock"),
    ("esy_lock?", r"(?:^|/)(?:\w+\.)?esy.lock$"),
    (
        "npm_shrinkwrap_or_package_lock?",
        r"npm-shrinkwrap\.json|package-lock\.json",
    ),
    ("pnpm_lock?", r"pnpm-lock\.yaml"),
    ("bun_lock?", r"(?:^|/)bun\.lockb?$"),
    ("terraform_lock?", r"(?:^|/)\.terraform\.lock\.hcl$"),
    ("generated_yarn_plugnplay?", r"(?:^|/)\.pnp\..*$"),
    ("godeps?", r"Godeps/"),
    ("generated_by_zephir?", r".\.zep\.(?:c|h|php)$"),
    ("htmlcov?", r"(?:^|/)htmlcov/"),
    ("pipenv_lock?", r"Pipfile\.lock"),
    ("gradle_wrapper?", r"(?i)(?:^|/)gradlew(?:\.bat)?$"),
    ("maven_wrapper?", r"(?i)(?:^|/)mvnw(?:\.cmd)?$"),
    ("mise_lock?", r"(?:^|/)mise(?:\.[^/]+)?\.lock$"),
    ("secrets_baseline?", r"(?:^|/)\.secrets\.baseline$"),
    (
        "julia_manifest?",
        r"(?:^|/)(?:Julia)?Manifest(?:-v\d+\.\d+)?\.toml$",
    ),
    ("generated_pascal_tlb?", r"(?i)_tlb\.pas$"),
    (
        "generated_sqlx_query?",
        r"(?:^|/)\.sqlx/query-[a-f\d]{64}\.json$",
    ),
];

/// 내용 규칙이 보는 것.
pub struct Ctx<'a> {
    pub path: &'a str,
    /// Ruby `File.extname`: 마지막 `.` 부터(점으로 시작하는 이름 `.bashrc` 는 확장자가 없다). 대소문자 그대로.
    pub extname: &'a str,
    /// 앞부분을 `\n` 으로 가른 줄(끝의 빈 줄도 남긴다 — Ruby `split("\n", -1)`).
    pub lines: Vec<&'a str>,
}

impl Ctx<'_> {
    fn line(&self, i: usize) -> &str {
        self.lines.get(i).copied().unwrap_or("")
    }

    fn first(&self, n: usize) -> &[&str] {
        &self.lines[..self.lines.len().min(n)]
    }

    fn ext_in(&self, list: &[&str]) -> bool {
        list.contains(&self.extname)
    }
}

type Check = fn(&Ctx<'_>) -> bool;

fn re(pattern: &str) -> Regex {
    Regex::new(pattern).expect("generated rule pattern")
}

/// 확장자와 앞 줄만 보는 규칙. 이름은 generated.rb 의 메서드 이름이다.
pub const CONTENT_RULES: &[(&str, Check)] = &[
    ("xcode_file?", |c| {
        c.ext_in(&[".nib", ".xcworkspacedata", ".xcuserstate"])
    }),
    ("minified_files?", |c| {
        let ext = c.extname.to_ascii_lowercase();
        if !(ext == ".js" || ext == ".css") || c.lines.is_empty() {
            return false;
        }
        let total: usize = c.lines.iter().map(|l| l.chars().count()).sum();
        total / c.lines.len() > 110
    }),
    ("source_map?", |c| {
        static NAME: LazyLock<Regex> = LazyLock::new(|| re(r"(?i)(?:\.css|\.js)\.map$"));
        static V2: LazyLock<Regex> = LazyLock::new(|| re(r#"^\{"version":\d+,"#));
        c.extname.eq_ignore_ascii_case(".map")
            && (NAME.is_match(c.path)
                || V2.is_match(c.line(0))
                || c.line(0).starts_with("/** Begin line maps. **/{"))
    }),
    ("compiled_coffeescript?", |c| {
        c.extname == ".js" && c.line(0).starts_with("// Generated by ")
    }),
    ("generated_parser?", |c| {
        static PEG: LazyLock<Regex> =
            LazyLock::new(|| re(r"^(?:[^/]|/[^*])*/\*(?:[^*]|\*[^/])*Generated by PEG.js"));
        c.extname == ".js" && PEG.is_match(&c.first(5).concat())
    }),
    ("generated_go?", |c| {
        c.extname == ".go"
            && c.lines.len() > 1
            && c.first(40)
                .iter()
                .any(|l| l.starts_with("// Code generated "))
    }),
    ("generated_protocol_buffer_from_go?", |c| {
        c.extname == ".proto"
            && c.lines.len() > 1
            && c.first(20)
                .iter()
                .any(|l| l.contains("This file was autogenerated by go-to-protobuf"))
    }),
    ("generated_protocol_buffer?", |c| {
        c.ext_in(&[".py", ".java", ".h", ".cc", ".cpp", ".m", ".rb", ".php"])
            && c.lines.len() > 1
            && c.first(3)
                .iter()
                .any(|l| l.contains("Generated by the protocol buffer compiler.  DO NOT EDIT!"))
    }),
    ("generated_javascript_protocol_buffer?", |c| {
        c.extname == ".js"
            && c.lines.len() > 6
            && c.line(5).contains("GENERATED CODE -- DO NOT EDIT!")
    }),
    ("generated_typescript_protocol_buffer?", |c| {
        c.extname == ".ts"
            && c.lines.len() > 4
            && c.line(0)
                .contains("Code generated by protoc-gen-ts_proto. DO NOT EDIT.")
    }),
    ("generated_twirp_ruby?", |c| {
        c.extname == ".rb"
            && c.lines.len() > 1
            && c.first(3).iter().any(|l| {
                l.contains("Code generated by protoc-gen-twirp_ruby") && l.contains("DO NOT EDIT.")
            })
    }),
    ("generated_apache_thrift?", |c| {
        c.ext_in(&[
            ".rb", ".py", ".go", ".js", ".m", ".java", ".h", ".cc", ".cpp", ".php",
        ]) && c
            .first(6)
            .iter()
            .any(|l| l.contains("Autogenerated by Thrift Compiler"))
    }),
    ("generated_jni_header?", |c| {
        c.extname == ".h"
            && c.lines.len() > 2
            && c.line(0)
                .contains("/* DO NOT EDIT THIS FILE - it is machine generated */")
            && c.line(1).contains("#include <jni.h>")
    }),
    ("generated_antlr?", |c| {
        c.extname == ".g" && c.lines.len() > 2 && c.line(1).contains("generated by Xtest")
    }),
    ("compiled_cython_file?", |c| {
        c.ext_in(&[".c", ".cpp"]) && c.lines.len() > 1 && c.line(0).contains("Generated by Cython")
    }),
    ("generated_module?", |c| {
        c.extname == ".mod"
            && c.lines.len() > 1
            && (c.line(0).contains("PCBNEW-LibModule-V")
                || c.line(0).contains("GFORTRAN module version '"))
    }),
    ("generated_unity3d_meta?", |c| {
        c.extname == ".meta" && c.lines.len() > 1 && c.line(0).contains("fileFormatVersion: ")
    }),
    ("generated_racc?", |c| {
        c.extname == ".rb"
            && c.lines.len() > 2
            && c.line(2)
                .starts_with("# This file is automatically generated by Racc")
    }),
    ("generated_jflex?", |c| {
        c.extname == ".java"
            && c.lines.len() > 1
            && c.line(0)
                .starts_with("/* The following code was generated by JFlex ")
    }),
    ("generated_grammarkit?", |c| {
        c.extname == ".java"
            && c.lines.len() > 1
            && c.line(0)
                .starts_with("// This is a generated file. Not intended for manual editing.")
    }),
    ("generated_roxygen2?", |c| {
        c.extname == ".Rd"
            && c.lines.len() > 1
            && c.line(0)
                .contains("% Generated by roxygen2: do not edit by hand")
    }),
    ("generated_html?", |c| {
        static DOXYGEN: LazyLock<Regex> =
            LazyLock::new(|| re(r"(?i)<!--\s+Generated by Doxygen\s+[.0-9]+\s*-->"));
        let ext = c.extname.to_ascii_lowercase();
        if !matches!(ext.as_str(), ".html" | ".htm" | ".xhtml") || c.lines.len() <= 1 {
            return false;
        }
        c.first(2)
            .iter()
            .any(|l| l.contains("<!-- Generated by pkgdown: do not edit by hand -->"))
            || (c.lines.len() > 2
                && c.line(2)
                    .starts_with("<!-- This is an automatically generated file."))
            || c.first(31).iter().any(|l| DOXYGEN.is_match(l))
    }),
    ("generated_jison?", |c| {
        c.extname == ".js"
            && c.lines.len() > 1
            && (c.line(0).starts_with("/* parser generated by jison ")
                || c.line(0).starts_with("/* generated by jison-lex "))
    }),
    ("generated_grpc_cpp?", |c| {
        c.ext_in(&[".cpp", ".hpp", ".h", ".cc"])
            && c.lines.len() > 1
            && c.line(0).starts_with("// Generated by the gRPC")
    }),
    ("generated_dart?", |c| {
        static DART: LazyLock<Regex> = LazyLock::new(|| re(r"generated code\W{2,3}do not modify"));
        c.extname == ".dart"
            && c.lines.len() > 1
            && c.first(3).iter().any(|l| DART.is_match(&l.to_lowercase()))
    }),
    ("generated_perl_ppport_header?", |c| {
        c.path.ends_with("ppport.h")
            && c.lines.len() > 10
            && c.line(8).contains("Automatically created by Devel::PPPort")
    }),
    ("generated_gamemakerstudio?", |c| {
        static JSON: LazyLock<Regex> = LazyLock::new(|| re(r"^\s*[\{\[]"));
        static LEGACY: LazyLock<Regex> = LazyLock::new(|| re(r"^\d\.\d\.\d.+\|\{"));
        c.ext_in(&[".yy", ".yyp"])
            && c.lines.len() > 3
            && (JSON.is_match(&c.first(3).concat()) || LEGACY.is_match(c.line(0)))
    }),
    ("generated_gimp?", |c| {
        static IMAGE: LazyLock<Regex> =
            LazyLock::new(|| re(r"^/\* GIMP [a-zA-Z0-9\- ]+ C\-Source image dump \(.+?\.c\) \*/"));
        static HEADER: LazyLock<Regex> = LazyLock::new(|| {
            re(r"^/\*  GIMP header image file format \([a-zA-Z0-9\- ]+\): .+?\.h  \*/")
        });
        c.ext_in(&[".c", ".h"])
            && !c.lines.is_empty()
            && (IMAGE.is_match(c.line(0)) || HEADER.is_match(c.line(0)))
    }),
    ("generated_visualstudio6?", |c| {
        c.extname.eq_ignore_ascii_case(".dsp")
            && c.first(3)
                .iter()
                .any(|l| l.contains("# Microsoft Developer Studio Generated Build File"))
    }),
    ("generated_haxe?", |c| {
        c.ext_in(&[".js", ".py", ".lua", ".cpp", ".h", ".java", ".cs", ".php"])
            && c.first(3).iter().any(|l| l.contains("Generated by Haxe"))
    }),
    ("generated_jooq?", |c| {
        c.extname.eq_ignore_ascii_case(".java")
            && c.first(2)
                .iter()
                .any(|l| l.contains("This file is generated by jOOQ."))
    }),
    ("generated_sorbet_rbi?", |c| {
        static TAPIOCA: LazyLock<Regex> = LazyLock::new(|| {
            re(r"^# Please (?:run|instead update this file by running) `bin/tapioca")
        });
        c.extname.eq_ignore_ascii_case(".rbi")
            && c.lines.len() >= 5
            && c.line(0).starts_with("# typed:")
            && c.line(2).contains("DO NOT EDIT MANUALLY")
            && TAPIOCA.is_match(c.line(4))
    }),
    ("generated_mysql_view_definition_format?", |c| {
        c.extname.eq_ignore_ascii_case(".frm") && c.line(0).contains("TYPE=VIEW")
    }),
];

/// Ruby `File.extname`.
pub fn extname(path: &str) -> &str {
    let name = path.rsplit('/').next().unwrap_or(path);
    match name.rfind('.') {
        Some(0) | None => "",
        Some(i) if i + 1 == name.len() => "",
        Some(i) => &name[i..],
    }
}

/// 맞은 규칙의 이름. `path` 는 저장소 기준 경로(없으면 파일 이름), `head` 는 파일 앞부분.
pub fn generated(path: &str, head: Option<&str>) -> Option<&'static str> {
    static PATHS: LazyLock<RegexSet> = LazyLock::new(|| {
        RegexSet::new(PATH_RULES.iter().map(|(_, p)| *p)).expect("generated path rules")
    });
    if let Some(i) = PATHS.matches(path).iter().next() {
        return Some(PATH_RULES[i].0);
    }
    let ctx = Ctx {
        path,
        extname: extname(path),
        lines: head.map_or_else(Vec::new, |h| h.split('\n').collect()),
    };
    CONTENT_RULES
        .iter()
        .find(|(_, check)| check(&ctx))
        .map(|(name, _)| *name)
}
